using AcademyDesk.Api.Data;using AcademyDesk.Api.Domain.Entities;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace AcademyDesk.Api.Controllers;
[ApiController][Route("api/academies/{academyId:guid}/lesson-plans")]public sealed class LessonPlansController(AcademyDeskDbContext db):ControllerBase{[HttpGet]public async Task<ActionResult> List(Guid academyId,CancellationToken t)=>Ok(await db.LessonPlans.AsNoTracking().Where(x=>x.AcademyId==academyId).OrderByDescending(x=>x.CreatedAtUtc).Select(x=>new{x.Id,x.BatchId,x.CourseModuleId,x.ClassSessionId,x.Title,x.Objectives,x.Status}).ToListAsync(t));[HttpPost]public async Task<ActionResult> Create(Guid academyId,CreateLessonPlan r,CancellationToken t){if(string.IsNullOrWhiteSpace(r.Title)||!await db.Batches.AnyAsync(x=>x.Id==r.BatchId&&x.AcademyId==academyId,t))return BadRequest(new{message="Valid batch and title required."});db.LessonPlans.Add(new LessonPlan{AcademyId=academyId,BatchId=r.BatchId,CourseModuleId=r.CourseModuleId,ClassSessionId=r.ClassSessionId,Title=r.Title.Trim(),Objectives=r.Objectives?.Trim()});await db.SaveChangesAsync(t);return Ok();}[HttpPatch("{id:guid}")]public async Task<ActionResult> Status(Guid academyId,Guid id,UpdateLessonStatus r,CancellationToken t){if(r.Status is not("Planned" or "Delivered" or "Skipped" or "MakeupNeeded"))return BadRequest();var x=await db.LessonPlans.SingleOrDefaultAsync(v=>v.Id==id&&v.AcademyId==academyId,t);if(x is null)return NotFound();x.Status=r.Status;await db.SaveChangesAsync(t);return Ok();}}
public sealed record CreateLessonPlan(Guid BatchId,Guid? CourseModuleId,Guid? ClassSessionId,string Title,string? Objectives);
public sealed record UpdateLessonStatus(string Status);
